# Assemble tools/packer.s for a ring layout and emit src/packer_blob.h (blob + matching PK_* constants), so the
# UPHY packer and the host reader can't disagree. Needs WSL + nix (llvm-mc). Usage: gen_packer.py IN_BASE IN_WORDS OUT_BASE OUT_END
import os, subprocess, sys
in_base, in_words, out_base, out_end = (int(a, 0) for a in sys.argv[1:5]); spin = int(sys.argv[5], 0) if len(sys.argv) > 5 else 64
assert in_base % 8 == 0 and out_base % 8 == 0 and in_words % 2 == 0 and (out_end - out_base) % 4 == 0
here = os.path.dirname(os.path.abspath(__file__)); tools = os.path.join(here, '..', 'tools')
wsl_tools = '/mnt/' + os.path.abspath(tools)[0].lower() + os.path.abspath(tools)[2:].replace('\\', '/')
sym = f'--defsym IN_BASE={in_base:#x} --defsym IN_END={in_base + 4 * in_words:#x} --defsym OUT_BASE={out_base:#x} --defsym OUT_END={out_end:#x} --defsym IDLE_SPIN={spin}'
cmd = f'cd {wsl_tools} && nix shell nixpkgs#llvmPackages.llvm -c bash -c "llvm-mc --triple=riscv32 -mattr=+m -filetype=obj {sym} packer.s -o packer.o && llvm-objcopy -O binary -j .text packer.o packer.bin"'
subprocess.run(['wsl', '-e', 'bash', '-lc', cmd], check=True)
b = open(os.path.join(tools, 'packer.bin'), 'rb').read()
out = [f'// Generated by gen_packer.py from tools/packer.s ({len(b)} bytes). Do not edit by hand.', '#pragma once', '#include <stdint.h>',
       f'constexpr uint32_t PK_IN_BASE = {in_base:#x}, PK_IN_LEN = {in_words}, PK_OUT_BASE = {out_base:#x}, PK_OUT_WORDS = {(out_end - out_base) // 4};',
       'static const uint8_t PACKER_BLOB[] = {']
out += ['    ' + ', '.join(f'0x{x:02x}' for x in b[i:i + 16]) + ',' for i in range(0, len(b), 16)] + ['};', '']
open(os.path.join(here, 'src', 'packer_blob.h'), 'w').write('\n'.join(out))
print(f'packer {len(b)} B: in {in_base:#x} x{in_words} words, out {out_base:#x}-{out_end:#x} ({(out_end - out_base) // 4} words)')
